// `update(dt)` runs every frame; assign to `self.rotation` to turn the entity.
scene Demo {
    state speed: f32 = 0.7;

    camera Main {
        position: vec3(0.0, 2.0, 5.0);
        target: vec3(0.0, 0.5, 0.0);
    }

    entity Cube {
        mesh: Box {};
        position: vec3(0.0, 0.5, 0.0);

        update(dt: f32) {
            self.rotation *= quat.axis_angle(vec3(0.0, 1.0, 0.0), speed * dt);
        }
    }
}

// `on key_down(Key.Space)` runs when the key goes down; handlers may assign scene state.
scene Demo {
    state speed: f32 = 0.7;

    camera Main {
        position: vec3(0.0, 2.0, 5.0);
        target: vec3(0.0, 0.5, 0.0);
    }

    entity Cube {
        mesh: Box {};

        update(dt: f32) {
            self.rotation *= quat.axis_angle(vec3(0.0, 1.0, 0.0), speed * dt);
        }
    }

    on key_down(Key.Space) {
        speed = -speed;
    }
}

// A material's `fragment` runs per pixel on the GPU; the `fn` helpers it calls must be GPU-safe.
fn pulse(t: f32) -> f32 {
    return 0.65 + 0.35 * sin(t);
}

material Pulse {
    param tint: color = #6b5cff;
    param phase: f32 = 0.0;

    fragment(input: SurfaceInput) -> color {
        return color.linear(tint.rgb * pulse(phase), tint.a);
    }
}

scene Demo {
    camera Main {
        position: vec3(0.0, 2.0, 5.0);
        target: vec3(0.0, 0.5, 0.0);
    }

    entity Cube {
        mesh: Box {};
        material: Pulse { phase: bind(frame.time); };
    }
}

// Constants, structs and functions. A `fn` runs on the CPU and in materials; `cpu fn` is for CPU-only code.
const FLOOR_Y: f32 = -0.5;

struct Orbit {
    radius: f32;
    speed: f32;
}

fn orbit_position(orbit: Orbit, t: f32) -> vec3 {
    return vec3(cos(t * orbit.speed) * orbit.radius, 0.5, sin(t * orbit.speed) * orbit.radius);
}

scene Demo {
    camera Main {
        position: vec3(0.0, 4.0, 8.0);
        target: vec3(0.0, 0.5, 0.0);
    }

    entity Floor {
        mesh: Plane {};
        position: vec3(0.0, FLOOR_Y, 0.0);
    }

    entity Ball {
        mesh: Sphere { radius: 0.5; };

        update(dt: f32) {
            self.position = orbit_position(Orbit { radius: 2.0; speed: 1.5; }, frame.time);
        }
    }
}
